mapper.update:

update board
 set title=#{title}
 ,content=#{content}
 ,upt_member_idx=#{uptMemberIdx}
 ,upt_dttm=current_timestamp
where board_idx=#{boardIdx}
and del_yn='N'


update board
 set del_yn='Y'
 ,del_member_idx=#{delMemberIdx}
 ,del_dttm=current_timestamp
where board_idx=#{boardIdx}
and del_yn='N'
